1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `model.test.mjs` pins. Living inside `engine/scheduler/`
12	// makes the queue modules siblings, so the dashboard sits beside the mechanism it
13	// renders rather than reaching across the tree at it.
14	//
15	// `stripComments` is the one remaining cross-tree reach, and it is deliberate:
16	// `file-placement` flags it advisory and its own remedy sanctions exactly this case.
17	// Shortening it would mean copying a comment-stripper nearer, and a second stripper
18	// that drifts from the canonical one is worse than the distance.
19	
20	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
21	import { mostRecentAnchor, nextAnchor, periodMs } from '../../engine/scheduler/queue/anchors.mjs';
22	import {
23	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
24	} from '../../engine/scheduler/queue/leases.mjs';
25	import {
26	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
27	  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, STATE_LABELS,
28	  TRIAGE_LABELS, NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
29	  NEEDS_HUMAN_FAILURE, isBlockingPark,
30	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
31	  parseWorkItemTitle, parseWorkItemBody, hasLabel, labelNames,
32	} from '../../engine/scheduler/queue/work-item.mjs';
33	
34	export {
35	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
36	  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
37	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
38	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
39	};
40	
41	const ms = (t) => (t == null ? null : new Date(t).getTime());
42	
43	// --- where a declared pack's tasks live ---------------------------------------
44	
45	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
46	// activation (core's rule), and the mount carries packs a repo never declared. So
47	// the roster is built from the declaration list, and a task directory belonging to
48	// an undeclared pack is skipped rather than rendered greyed-out.
49	//
50	// Two roots, because the same code reads the canon home and a member: the home
51	// runs from the repo root (`packs/<id>`), a member from the mount
52	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
53	// from `.claudinite/local/packs/<name>` in both.
54	export function declaredPackDirs(config) {
55	  const dirs = new Map();
56	  for (const entry of config?.packs ?? []) {
57	    const id = typeof entry === 'string' ? entry : entry?.id;
58	    if (!id) continue;
59	    if (id.startsWith('local/')) {
60	      const name = id.slice('local/'.length);
61	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
62	    } else {
63	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
64	    }
65	  }
66	  return dirs;
67	}
68	
69	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.mjs$/;
70	
71	// Every declared pack's task declarations, from one recursive tree listing.
72	// `paths` is the flat list of blob paths the tree API returned.
73	export function taskDeclarationPaths(paths, config) {
74	  const dirs = declaredPackDirs(config);
75	  const found = [];
76	  for (const path of paths ?? []) {
77	    const m = TASK_PATH_RE.exec(path);
78	    if (!m) continue;
79	    const [, packDir, task] = m;
80	    for (const [pack, roots] of dirs) {
81	      if (roots.includes(packDir)) found.push({ pack, task, path });
82	    }
83	  }
84	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
85	}
86	
87	// --- reading a task declaration -----------------------------------------------
88	
89	// The declaration is a JS object literal, and the page reads it as TEXT: it renders
90	// other repos over the API, where there is nothing to import and no Node to import
91	// it with. So the scalar fields are lifted by pattern, over comment-stripped source
92	// — the engine's own `stripComments`, so a `// frequency: 'weekly'` in a task's
93	// header prose can never be mistaken for the declaration.
94	//
95	// A field this cannot read comes back NULL and renders as "unknown". It is never
96	// defaulted: a task whose declaration this misreads must look unreadable, because a
97	// plausible wrong frequency would silently move a next-anchor the whole roster is
98	// read for.
99	// The key must open the line or follow a `{` / `,` — anchoring on the line start
100	// alone would miss a declaration written on one line, and anchoring on nothing
101	// would let `code_work` be found inside `agent_code_work`. The value may close on a
102	// comma, the object's brace, or the line's end, so a last field without a trailing
103	// comma still reads.
104	const at = (field) => `(?:^|[{,])\\s*${field}:\\s*`;
105	
106	const scalar = (src, field) => {
107	  const m = new RegExp(`${at(field)}(?:'([^']*)'|"([^"]*)"|(\\d+)|(true|false))\\s*(?=[,}\\n]|$)`, 'm').exec(src);
108	  if (!m) return null;
109	  if (m[3] !== undefined) return Number(m[3]);
110	  if (m[4] !== undefined) return m[4] === 'true';
111	  return m[1] ?? m[2];
112	};
113	
114	const stringArray = (src, field) => {
115	  const m = new RegExp(`${at(field)}\\[([^\\]]*)\\]`, 'm').exec(src);
116	  if (!m) return null;
117	  return [...m[1].matchAll(/'([^']*)'|"([^"]*)"/g)].map((x) => x[1] ?? x[2]);
118	};
119	
120	export function parseDeclaration(text) {
121	  const src = stripComments(String(text ?? ''));
122	  return {
123	    id: scalar(src, 'id'),
124	    frequency: scalar(src, 'frequency'),
125	    agent_model: scalar(src, 'agent_model'),
126	    expected_outcome: scalar(src, 'expected_outcome'),
127	    interrupt_policy: scalar(src, 'interrupt_policy'),
128	    code_work: scalar(src, 'code_work'),
129	    agent_execution_timeout: scalar(src, 'agent_execution_timeout'),
130	    precondition_signals: stringArray(src, 'precondition_signals'),
131	    // A task may decline to run; whether it CAN is the difference between "did not
132	    // run" being routine and being a fault, so the roster shows it.
133	    has_precondition: /^\s*(?:async\s+)?precondition\s*\(/m.test(src),
134	  };
135	}
136	
137	// --- work items ----------------------------------------------------------------
138	
139	export const isWorkItem = (issue) => String(issue?.title ?? '').startsWith(WORK_PREFIX);
140	
141	// The one state label an open item wears, or null for an item wearing none — which
142	// is not a display quirk but the torn-label-swap leavings the janitor repairs, so
143	// it gets its own rendered state rather than being folded into "blocked".
144	export function stateOf(item) {
145	  if (item?.state === 'closed') return 'closed';
146	  if (hasLabel(item, NEEDS_HUMAN)) return NEEDS_HUMAN;
147	  const worn = STATE_LABELS.filter((l) => hasLabel(item, l));
148	  if (worn.length === 1) return worn[0];
149	  if (worn.length > 1) return 'torn';
150	  return 'unlabelled';
151	}
152	
153	// The park's sub-label, or null for one wearing none (an older engine's, or an
154	// agent that skipped it). An item can only wear one meaningfully; first wins.
155	export const triageOf = (item) => TRIAGE_LABELS.find((l) => hasLabel(item, l)) ?? null;
156	
157	const TRIAGE_TEXT = {
158	  [NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
159	  [NEEDS_HUMAN_ACTION]: 'something to change outside the code',
160	  [NEEDS_HUMAN_DECISION]: 'a decision to make',
161	  [NEEDS_HUMAN_FAILURE]: 'a break to diagnose, holding the task\'s lane',
162	};
163	
164	export function outcomeOf(item) {
165	  for (const o of [OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE]) if (hasLabel(item, o)) return o;
166	  return null;
167	}
168	
169	// How long the item has sat where it is. Every transition is a label write, so
170	// `updated_at` is the last touch — the same quantity the janitor's rules count.
171	const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));
172	
173	// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
174	// what the page flags is what the engine will actually act on — and how long the
175	// viewer waits for it.
176	export function warningsFor(item, now, { periodFor = () => null } = {}) {
177	  const out = [];
178	  const state = stateOf(item);
179	  const idle = idleMs(item, now);
180	  if (state === EXECUTING && idle >= EXECUTING_LEASH_MS) {
181	    out.push({ level: 'serious', text: 'executing past the leash — the next tick reclaims it' });
182	  }
183	  if (state === AGENT && idle >= AGENT_LEASH_MS) {
184	    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
185	  }
186	  if (state === READY) {
187	    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
188	    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
189	  }
190	  if (state === BLOCKED && idle >= STUCK_BLOCKED_MS) {
191	    out.push({ level: 'warning', text: 'blocked for over 2 days' });
192	  }
193	  if (state === NEEDS_HUMAN) {
194	    // What the park is asking for, and whether it is holding the task's lane —
195	    // an approval waiting on a reviewer is not the same alarm as a broken run
196	    // that has stopped its task being scheduled at all.
197	    const t = triageOf(item);
198	    out.push({
199	      level: isBlockingPark(item) ? 'critical' : 'warning',
200	      text: t ? `parked for a human — ${TRIAGE_TEXT[t]}` : 'parked for a human — unclassified, holding the task\'s lane',
201	    });
202	  }
203	  if (state === 'torn') out.push({ level: 'warning', text: 'wearing more than one state label' });
204	  if (state === 'unlabelled') out.push({ level: 'warning', text: 'open with no state label' });
205	  return out;
206	}
207	
208	// An open item, decorated with everything the queue lane renders.
209	export function describeItem(item, now, opts = {}) {
210	  const parsed = parseWorkItemTitle(item.title) ?? { pack: null, task: null, qualifier: null };
211	  const body = parseWorkItemBody(item.body);
212	  return {
213	    number: item.number,
214	    key: parsed.pack && parsed.task ? `${parsed.pack}/${parsed.task}` : null,
215	    ...parsed,
216	    state: stateOf(item),
217	    outcome: outcomeOf(item),
218	    urgent: hasLabel(item, URGENT),
219	    labels: labelNames(item),
220	    notBefore: body.notBefore,
221	    blockedBy: body.blockedBy,
222	    taskPath: body.taskPath,
223	    createdAt: item.created_at,
224	    updatedAt: item.updated_at,
225	    closedAt: item.closed_at ?? null,
226	    idleMs: idleMs(item, now),
227	    comments: item.comments ?? 0,
228	    warnings: warningsFor(item, now, opts),
229	  };
230	}
231	
232	// --- the roster ----------------------------------------------------------------
233	
234	// One row per DECLARED task, whether or not it has ever run — a task that has never
235	// produced an item is exactly the interesting case, and an issue-derived list would
236	// omit it entirely.
237	export function buildRoster({ tasks = [], items = [], now, schedule }) {
238	  const byKey = new Map();
239	  for (const it of items) {
240	    const p = parseWorkItemTitle(it.title);
241	    if (!p) continue;
242	    const key = `${p.pack}/${p.task}`;
243	    if (!byKey.has(key)) byKey.set(key, []);
244	    byKey.get(key).push(it);
245	  }
246	
247	  return tasks.map((t) => {
248	    const key = `${t.pack}/${t.task}`;
249	    const mine = (byKey.get(key) ?? []).slice()
250	      .sort((a, b) => ms(b.created_at) - ms(a.created_at));
251	    const open = mine.filter((i) => i.state === 'open');
252	    const closed = mine.filter((i) => i.state === 'closed');
253	    const freq = t.declaration?.frequency ?? null;
254	
255	    // A frequency this could not read yields no anchor rather than a guessed one,
256	    // and `manual` genuinely has none — the two are different and render differently.
257	    let next = null;
258	    let anchorNote = null;
259	    if (freq === 'manual') anchorNote = 'manual — only a hand-created item';
260	    else if (!freq) anchorNote = 'frequency unknown';
261	    else if (!schedule) anchorNote = 'no schedule configured';
262	    else next = nextAnchor(freq, schedule, now);
263	
264	    return {
265	      key,
266	      pack: t.pack,
267	      task: t.task,
268	      path: t.path,
269	      declaration: t.declaration ?? null,
270	      frequency: freq,
271	      nextAnchor: next,
272	      anchorNote,
273	      periodMs: freq && freq !== 'manual' ? periodMs(freq) : null,
274	      current: open.length ? describeItem(open[0], now, { periodFor: () => (freq ? periodMs(freq) : null) }) : null,
275	      openCount: open.length,
276	      lastClosed: closed.length ? describeItem(closed[0], now) : null,
277	      history: closed.map((i) => describeItem(i, now)),
278	    };
279	  });
280	}
281	
282	// Outcome tallies over the closed items the scan actually saw. `scanned` travels
283	// with them: every count here is over a window, and a window is not "all of it".
284	export function outcomeTally(rows) {
285	  const t = { [OUTCOME_DONE]: 0, [OUTCOME_DELIVERED]: 0, [OUTCOME_OBSOLETE]: 0, none: 0 };
286	  for (const r of rows) for (const h of r.history) t[h.outcome ?? 'none'] += 1;
287	  return t;
288	}
289	
290	// --- the protocol comments ------------------------------------------------------
291	
292	// Which of the three markers a comment carries. The markers are HTML comments so a
293	// human reading the issue sees prose; the page shows the protocol beat instead.
294	export function commentKind(body) {
295	  const b = String(body ?? '');
296	  if (b.includes(EPISODE_MARKER)) return 'episode';
297	  if (b.includes(HANDOFF_MARKER)) return 'handoff';
298	  if (b.includes(CLAIM_MARKER)) return 'claim';
299	  return null;
300	}
301

