1	// The fleet view's derivation — many members' raw reads in, one ranked overview out.
2	// Pure: no clock, no I/O, no DOM.
3	//
4	// A fleet page answers a different question from the per-repo one. Per repo the
5	// question is "what is this scheduler doing"; across a fleet it is "WHERE DO I NEED
6	// TO LOOK", and a page that answers the first question twelve times over does not
7	// answer the second. So nothing here is a total for its own sake: every number is
8	// either something that needs a human, something that is about to, or the context
9	// needed to tell those apart.
10	//
11	// Three ideas do the work:
12	//
13	//   ATTENTION IS EARNED, NOT COUNTED. A member surfaces because something is true of
14	//   it — an item parked, a leash blown, a scheduler failing, a mount that stopped
15	//   converging — and each of those arrives as a REASON with a severity, not as a
16	//   number to be summed. The ranking is over the worst reason, so a member with one
17	//   parked item outranks one with forty healthy work items.
18	//
19	//   ABSENCE IS A STATE. A member that does not run Claudinite, one the viewer cannot
20	//   read, and one that is running fine are three different answers and never collapse
21	//   into "0". A fleet view whose blanks are ambiguous is worse than no fleet view.
22	//
23	//   ONE MEMBER'S FAILURE IS ONE ROW'S PROBLEM. Every member is summarised
24	//   independently and a read that failed becomes a row saying so, so a single private
25	//   repo or a rate-limit stumble cannot blank the page.
26	
27	import { periodMs } from '../../engine/scheduler/queue/anchors.mjs';
28	import {
29	  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN, URGENT,
30	  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
31	} from '../../engine/scheduler/queue/work-item.mjs';
32	import { describeItem, isWorkItem, parseWorkItemTitle, taskDeclarationPaths } from './model.mjs';
33	
34	// Severity ladder, worst first. The order IS the sort, so it is stated once here
35	// rather than implied by comparisons scattered through the render.
36	export const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
37	const levelRank = (l) => {
38	  const i = LEVELS.indexOf(l);
39	  return i === -1 ? LEVELS.length : i;
40	};
41	
42	// How far behind a member's mount may drift before it is worth saying. A converge
43	// runs at least daily, so a member that has not moved in a week has stopped
44	// converging rather than merely lagged.
45	export const MOUNT_STALE_MS = 7 * 86400e3;
46	
47	const ms = (t) => (t == null ? null : new Date(t).getTime());
48	
49	// --- mount freshness ------------------------------------------------------------
50	
51	// Whether a member's mount is current. Judged on `ref` / `engineVersion` /
52	// `packVersions` and NEVER on `updated` alone: a held stamp pins `updated` behind a
53	// pending note while the mount keeps converging normally, so a member that is fine
54	// looks weeks stale by that field.
55	//
56	// `canon` is the reference to compare against, and it is optional — with no canon
57	// supplied the honest answer is `unknown`, not `current`.
58	export function mountState(stamp, canon = null, now = null) {
59	  if (!stamp) return { state: 'none', ref: null, engineVersion: null };
60	  const ref = stamp.ref ?? null;
61	  const engineVersion = stamp.engineVersion ?? null;
62	  const updated = stamp.updated ?? null;
63	
64	  if (!canon?.ref) {
65	    // No reference to compare with. `updated` cannot decide freshness, but a mount
66	    // that has not been touched in a week says something on its own: the converge
67	    // itself has stopped, whatever version it stopped on.
68	    const age = now && updated ? ms(now) - ms(updated) : null;
69	    if (age !== null && age >= MOUNT_STALE_MS) {
70	      return { state: 'stalled', ref, engineVersion, updated, age };
71	    }
72	    return { state: 'unknown', ref, engineVersion, updated, age };
73	  }
74	
75	  if (ref && ref === canon.ref) return { state: 'current', ref, engineVersion, updated };
76	
77	  // Behind, and the engine major is the part that matters: a member a few packs
78	  // behind converges on its own, a member on an older engine may not be able to.
79	  const behindEngine = Number.isInteger(engineVersion) && Number.isInteger(canon.engineVersion)
80	    && engineVersion < canon.engineVersion;
81	  if (behindEngine) return { state: 'behind-engine', ref, engineVersion, updated };
82	
83	  // Behind is routine — canon moves and members catch up within a day. Behind AND not
84	  // having converged in a week is not the same fact: that member is not catching up,
85	  // and the gap will only widen. Being behind must not mask a stopped converge.
86	  const age = now && updated ? ms(now) - ms(updated) : null;
87	  if (age !== null && age >= MOUNT_STALE_MS) return { state: 'stalled', ref, engineVersion, updated, age };
88	
89	  return { state: 'behind', ref, engineVersion, updated, age };
90	}
91	
92	// --- one member -----------------------------------------------------------------
93	
94	// Everything a fleet row shows about one member, plus the reasons it needs looking
95	// at. `read` is what the loader managed to fetch; a member it could not read arrives
96	// with `error` set and every other field absent.
97	export function summariseMember(read, { now, canon = null } = {}) {
98	  const {
99	    repo, error = null, declaration = null, items = null, runs = null, paths = null,
100	    prs = null, head = null, stars = null, defaultBranch = null,
101	  } = read ?? {};
102	
103	  if (error) {
104	    // A read the page DECLINED to make is not the same fact as one it could not make:
105	    // the repo is fine, the budget is not, and the row must not read as a fault of the
106	    // member. It is raised a rung above a permissions miss because it is the one the
107	    // viewer can act on — sign in, or wait for the reset.
108	    const withheld = error?.status === 'budget';
109	    return {
110	      repo,
111	      status: withheld ? 'withheld' : 'unreadable',
112	      level: withheld ? 'warning' : 'info',
113	      error,
114	      // Not being able to read a member is not the member being broken. It is almost
115	      // always a private repo outside this viewer's grant, so it is reported at the
116	      // bottom of the page rather than raised as an alarm.
117	      reasons: [{ level: withheld ? 'warning' : 'info', text: describeReadError(error) }],
118	    };
119	  }
120	
121	  if (!declaration) {
122	    return {
123	      repo,
124	      status: 'not-adopted',
125	      level: 'info',
126	      reasons: [{ level: 'info', text: 'does not run Claudinite' }],
127	    };
128	  }
129	
130	  const work = (items ?? []).filter(isWorkItem);
131	  const open = work.filter((i) => i.state === 'open');
132	  const closed = work.filter((i) => i.state === 'closed');
133	
134	  const declaredTasks = paths ? taskDeclarationPaths(paths, declaration).length : null;
135	  const periodFor = () => null;   // the fleet row needs no per-task cadence
136	  const described = open.map((i) => describeItem(i, now, { periodFor }));
137	
138	  const byState = { [BLOCKED]: 0, [READY]: 0, [EXECUTING]: 0, [AGENT]: 0, [NEEDS_HUMAN]: 0, other: 0 };
139	  for (const d of described) {
140	    if (byState[d.state] === undefined) byState.other += 1;
141	    else byState[d.state] += 1;
142	  }
143	
144	  const parked = described.filter((d) => d.state === NEEDS_HUMAN);
145	  const warned = described.filter((d) => d.state !== NEEDS_HUMAN && d.warnings.length);
146	
147	  const outcomes = { [OUTCOME_DONE]: 0, [OUTCOME_DELIVERED]: 0, [OUTCOME_OBSOLETE]: 0, none: 0 };
148	  for (const i of closed) {
149	    const labels = i.labels ?? [];
150	    const o = [OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE].find((x) => labels.includes(x));
151	    outcomes[o ?? 'none'] += 1;
152	  }
153	
154	  const lastActivity = closed
155	    .map((i) => ms(i.closed_at) ?? ms(i.updated_at))
156	    .filter(Boolean)
157	    .sort((a, b) => b - a)[0] ?? null;
158	
159	  const runSummary = summariseRuns(runs ?? [], now);
160	  const ci = ciStatus(runs ?? [], defaultBranch);
161	  const mount = mountState(declaration.claudinite, canon, now);
162	
163	  const reasons = [];
164	  if (parked.length) {
165	    reasons.push({ level: 'critical', text: `${parked.length} item${parked.length > 1 ? 's' : ''} parked for a human` });
166	  }
167	  if (runSummary.consecutiveFailures > 0) {
168	    reasons.push({
169	      level: runSummary.consecutiveFailures > 1 ? 'critical' : 'serious',
170	      text: `scheduler last run failed${runSummary.consecutiveFailures > 1 ? ` (${runSummary.consecutiveFailures} in a row)` : ''}`,
171	    });
172	  }
173	  if (warned.length) {
174	    reasons.push({ level: 'serious', text: `${warned.length} item${warned.length > 1 ? 's' : ''} past a leash` });
175	  }
176	  if (mount.state === 'behind-engine') {
177	    reasons.push({ level: 'serious', text: `mount is on engine v${mount.engineVersion}, canon is v${canon?.engineVersion}` });
178	  } else if (mount.state === 'stalled') {
179	    reasons.push({
180	      level: 'warning',
181	      text: `mount has not converged in ${Math.floor(mount.age / 86400e3)} days`,
182	    });
183	  } else if (mount.state === 'behind') {
184	    reasons.push({ level: 'info', text: 'mount is behind canon' });
185	  } else if (mount.state === 'none') {
186	    reasons.push({ level: 'warning', text: 'declares Claudinite but carries no mount stamp' });
187	  }
188	  // A repo that declares tasks and has never produced a work item is not idle — its
189	  // scheduler is not running. That is invisible in every per-repo number here, which
190	  // is exactly why the fleet view is the place it shows up.
191	  if (declaredTasks !== null && declaredTasks > 0 && work.length === 0) {
192	    reasons.push({ level: 'serious', text: `${declaredTasks} task${declaredTasks > 1 ? 's' : ''} declared, no work item ever created` });
193	  }
194	  if (ci.state === 'failing') {
195	    // The member's own CI, said in the member's own words: this is not the scheduler
196	    // failing, and the two must not read as the same alarm.
197	    reasons.push({ level: 'warning', text: 'the repo\'s own CI is failing on its default branch' });
198	  }
199	  if (declaration.packs?.length === 0) {
200	    reasons.push({ level: 'warning', text: 'declares no packs' });
201	  }
202	
203	  const level = reasons.length ? reasons.map((r) => r.level).sort((a, b) => levelRank(a) - levelRank(b))[0] : 'ok';
204	
205	  return {
206	    repo,
207	    status: 'adopted',
208	    level,
209	    reasons,
210	    packs: (declaration.packs ?? []).map((p) => (typeof p === 'string' ? p : p?.id)).filter(Boolean),
211	    declaredTasks,
212	    open: { total: open.length, byState, urgent: described.filter((d) => d.urgent).length },
213	    parked: parked.length,
214	    warned: warned.length,
215	    closedSeen: closed.length,
216	    outcomes,
217	    lastActivity,
218	    runs: runSummary,
219	    ci,
220	    stars,
221	    lastCommit: head?.committedAt ? ms(head.committedAt) : null,
222	    work: humanWork(items, prs, now),
223	    mount,
224	    schedule: declaration.taskScheduler ?? null,
225	  };
226	}
227	
228	// A read that failed says something different depending on how. 404 on a repo the
229	// roster names is almost always "not shared with this viewer", which is a permissions
230	// fact rather than a fault.
231	function describeReadError(error) {
232	  const status = error?.status;
233	  if (status === 'budget') return 'not read — this page is holding back your last requests; sign in or wait for the reset';
234	  if (status === 404) return 'not visible to you — the roster names it, your credential cannot see it';
235	  if (status === 403) return 'forbidden — rate limit, or your credential lacks access';
236	  if (status === 401) return 'your credential was rejected';
237	  return error?.message ? `unreadable — ${error.message}` : 'unreadable';
238	}
239	
240	// The repo's OWN CI, which is a different question from the scheduler's health: one
241	// says whether this project builds, the other whether Claudinite is running here. They
242	// are read from the same list and must never be conflated — a green scheduler on a
243	// repo whose tests are red is not a healthy member.
244	//
245	// The default branch's most recent completed run is the answer; a `schedule` run is
246	// excluded because that is the queue's own tick, reported separately.
247	export function ciStatus(runs, defaultBranch) {
248	  const mine = (runs ?? []).filter((r) => r.event !== 'schedule'
249	    && (!defaultBranch || !r.head_branch || r.head_branch === defaultBranch));
250	  const inFlight = mine.some((r) => r.status === 'in_progress' || r.status === 'queued');
251	  const last = mine.find((r) => r.status === 'completed');
252	  if (!last) return { state: inFlight ? 'running' : 'unknown', at: null, name: null };
253	  const state = last.conclusion === 'success' ? 'passing'
254	    : (last.conclusion === 'cancelled' || last.conclusion === 'skipped') ? 'unknown'
255	      : 'failing';
256	  return { state: inFlight ? 'running' : state, at: ms(last.created_at), name: last.name ?? null, url: last.html_url ?? null };
257	}
258	
259	// What is waiting on a PERSON here, as opposed to on the queue: issues that are not
260	// Claudinite work items, and open pull requests. Both come out of the issue page the
261	// row already reads, so this costs nothing and stops at that window — an issue older
262	// than the window is not counted, and the panel says the window is a window.
263	export function humanWork(items, prs, now) {
264	  const open = (items ?? []).filter((i) => i.state === 'open' && !isWorkItem(i));
265	  const oldest = (list) => list.map((i) => ms(i.created_at)).filter(Boolean).sort((a, b) => a - b)[0] ?? null;
266	  const openPrs = (prs ?? []).filter((p) => !p.draft);
267	  return {
268	    issues: open.length,
269	    issuesOldest: oldest(open),
270	    prs: openPrs.length,
271	    drafts: (prs ?? []).length - openPrs.length,
272	    prsOldest: oldest(openPrs),
273	    now,
274	  };
275	}
276	
277	// The scheduler's own health. Only the workflow that drives the queue matters here —
278	// a failing unrelated CI run is the repo's business, not the fleet scheduler's — so
279	// runs are filtered to scheduled ones before anything is counted.
280	export function summariseRuns(runs, now) {
281	  const scheduled = runs.filter((r) => r.event === 'schedule');
282	  const completed = scheduled.filter((r) => r.status === 'completed');
283	  const inFlight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued').length;
284	
285	  // Consecutive failures from the most recent backwards: one failure is noise, a run
286	  // of them is a member that has stopped working.
287	  let consecutiveFailures = 0;
288	  for (const r of completed) {
289	    if (r.conclusion === 'success') break;
290	    if (r.conclusion === 'cancelled' || r.conclusion === 'skipped') continue;
291	    consecutiveFailures += 1;
292	  }
293	
294	  const lastAt = scheduled.map((r) => ms(r.created_at)).filter(Boolean).sort((a, b) => b - a)[0] ?? null;
295	
296	  return {
297	    scheduled: scheduled.length,
298	    inFlight,
299	    consecutiveFailures,
300	    lastAt,
301	    // No scheduled run at all is not "healthy" — it is "we have never seen this
302	    // member's scheduler", which the row must be able to say.
303	    everRan: scheduled.length > 0,
304	  };
305	}
306	
307	// --- the fleet ------------------------------------------------------------------
308	
309	// Worst first, then by how much is waiting. Ties break on the repo name so the order
310	// is stable across loads — a table that reshuffles under you is unreadable.
311	export function rankMembers(summaries) {
312	  return [...summaries].sort((a, b) =>
313	    levelRank(a.level) - levelRank(b.level)
314	    || (b.parked ?? 0) - (a.parked ?? 0)
315	    || (b.warned ?? 0) - (a.warned ?? 0)
316	    || (b.open?.total ?? 0) - (a.open?.total ?? 0)
317	    || a.repo.localeCompare(b.repo));
318	}
319	
320	// The headline numbers. Each is a count of MEMBERS needing something, not a count of
321	// things — "3 members need you" is actionable where "47 open items" is not.
322	export function rollUp(summaries) {
323	  const adopted = summaries.filter((s) => s.status === 'adopted');
324	  const outcomes = { [OUTCOME_DONE]: 0, [OUTCOME_DELIVERED]: 0, [OUTCOME_OBSOLETE]: 0, none: 0 };
325	  for (const s of adopted) for (const [k, v] of Object.entries(s.outcomes ?? {})) outcomes[k] += v;
326	
327	  return {
328	    members: summaries.length,
329	    adopted: adopted.length,
330	    notAdopted: summaries.filter((s) => s.status === 'not-adopted').length,
331	    unreadable: summaries.filter((s) => s.status === 'unreadable').length,
332	    withheld: summaries.filter((s) => s.status === 'withheld').length,
333	    needAttention: adopted.filter((s) => levelRank(s.level) <= levelRank('serious')).length,
334	    parkedMembers: adopted.filter((s) => s.parked > 0).length,
335	    parkedItems: adopted.reduce((n, s) => n + s.parked, 0),
336	    warnedMembers: adopted.filter((s) => s.warned > 0).length,
337	    failingMembers: adopted.filter((s) => s.runs?.consecutiveFailures > 0).length,
338	    neverRan: adopted.filter((s) => s.runs && !s.runs.everRan).length,
339	    behindMembers: adopted.filter((s) => ['behind', 'behind-engine', 'stalled'].includes(s.mount?.state)).length,
340	    openItems: adopted.reduce((n, s) => n + (s.open?.total ?? 0), 0),
341	    inFlight: adopted.reduce((n, s) => n + (s.runs?.inFlight ?? 0), 0),
342	    declaredTasks: adopted.reduce((n, s) => n + (s.declaredTasks ?? 0), 0),
343	    outcomes,
344	  };
345	}
346	
347	// Which packs the fleet uses, and how widely. Answers the question the canon actually
348	// asks of its fleet — "who would a change to this pack reach" — which no single
349	// member's page can.
350	export function packSpread(summaries) {
351	  const counts = new Map();
352	  for (const s of summaries) {
353	    for (const p of s.packs ?? []) counts.set(p, (counts.get(p) ?? 0) + 1);
354	  }
355	  return [...counts.entries()]
356	    .map(([pack, members]) => ({ pack, members }))
357	    .sort((a, b) => b.members - a.members || a.pack.localeCompare(b.pack));
358	}
359	
360	// Which tasks are running across the fleet, from the work items themselves. A task
361	// declared by a shared pack runs in many members, and its fleet-wide behaviour —
362	// especially a task that is parked in several at once — is a canon problem rather
363	// than any one member's.
364	export function taskSpread(reads, now) {
365	  const byTask = new Map();
366	  for (const read of reads) {
367	    for (const item of (read.items ?? []).filter(isWorkItem)) {
368	      const parsed = parseWorkItemTitle(item.title);
369	      if (!parsed) continue;
370	      const key = `${parsed.pack}/${parsed.task}`;
371	      if (!byTask.has(key)) byTask.set(key, { key, pack: parsed.pack, task: parsed.task, members: new Set(), open: 0, parked: 0, done: 0, failed: 0 });
372	      const row = byTask.get(key);
373	      row.members.add(read.repo);
374	      if (item.state === 'open') {
375	        row.open += 1;
376	        if ((item.labels ?? []).includes(NEEDS_HUMAN)) row.parked += 1;
377	      } else {
378	        const labels = item.labels ?? [];
379	        if (labels.includes(OUTCOME_DONE) || labels.includes(OUTCOME_DELIVERED)) row.done += 1;
380	        else if (!labels.includes(OUTCOME_OBSOLETE)) row.failed += 1;
381	      }
382	    }
383	  }
384	  return [...byTask.values()]
385	    .map((r) => ({ ...r, members: r.members.size }))
386	    .sort((a, b) => b.parked - a.parked || b.members - a.members || a.key.localeCompare(b.key));
387	}
388	
389	export { URGENT };
