126	// Title. The optional qualifier exists ONLY for deliberately concurrent items —
127	// a fan-out naming its target — and it is part of the identity the same-title
128	// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
129	// grammar, and the issue number is the identity (DESIGN §5).
130	export const workItemTitle = ({ pack, task, qualifier = null }) =>
131	  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;
132	
133	// pack and task ids are single path segments; the qualifier is whatever follows.
134	const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;
135	
136	// The pack half is canonicalized on the way out. A work item's title is STORED
137	// DATA — it sits on an open GitHub issue that outlives any one converge — so items
138	// filed before a pack was renamed still carry the old spelling. Read literally, the
139	// tick would not recognise its own live item, would file a second one beside it, and
140	// would leave the first orphaned in the queue with nothing ever draining it.
141	export function parseWorkItemTitle(title) {
142	  const m = TITLE_RE.exec(String(title ?? '').trim());
143	  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
144	}
145	
146	export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;
147	
148	// --- comment markers ----------------------------------------------------------
149	// The three comments the protocol reads back. They are HTML comments so a human
150	// reading the item sees prose, and they are here — with the labels and the body
151	// fields — because together they ARE the item's vocabulary, the one compatibility
152	// surface across engine versions (DESIGN §14).
153	//
154	// The CLAIM comment carries who and when (executor identity is an unbounded set
155	// and must never become a label). The HANDOFF comment names the session and the
156	// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
157	// scoped to: every claim before it is dead, and arbitrating over dead claims makes
158	// one outrank every future live claimant — the item then livelocks through reclaim
159	// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
160	export const CLAIM_MARKER = '<!-- claudinite-claim -->';
161	export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
162	export const EPISODE_MARKER = '<!-- claudinite-episode -->';
163	
164	// --- the body -----------------------------------------------------------------
165	
166	export const NOT_BEFORE_FIELD = 'Not-before';
167	export const BLOCKED_BY_FIELD = 'Blocked-by';
168	
169	// The heading the delivered-artifacts section carries in a work item body. One
170	// home, because it is written in three places and MATCHED when a re-entrant run
171	// updates the section it already wrote.
172	export const DELIVERED_HEADING = 'Delivered by code-work';
173	
174	// The same heading as earlier renames spelled it. A live item's body still carries
175	// whichever word was current when its section was first written, and matching only
176	// today's would append a SECOND section rather than updating that one.
177	export const LEGACY_DELIVERED_HEADINGS = Object.freeze([
178	  'Delivered by prework',
179	  'Delivered by code_work',
180	]);
181	
182	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
183	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
184	
185	// Build a work item body. The first line is the task path — the only thing an
186	// executor reads to locate the worker, validated in code before anything trusts
187	// it. Everything behavior-defining (model, ceiling, worker content, code-work
188	// command) is read from the tracked task files at HEAD, never from here.
189	export function workItemBody({
190	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
191	}) {
192	  const lines = [taskPath, ''];
193	  const fields = [];
194	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
195	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
