212	// with no first line, or whose fields are absent, yields nulls — absence is
213	// meaningful everywhere here and is never filled in with a default.
214	export function parseWorkItemBody(body) {
215	  const text = String(body ?? '');
216	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
