230	// bounds `withSection` writes to — and only `- ` bullets count, so the prose
231	// framing around a section contributes nothing.
232	export function parseContextLines(body) {
233	  const lines = String(body ?? '').split('\n');
234	  const at = lines.findIndex((l) => l.trim() === '### Context');
235	  if (at === -1) return [];
236	  const out = [];
237	  for (const line of lines.slice(at + 1)) {
238	    if (line.startsWith('### ')) break;
239	    const m = /^-[ \t]+(.*)$/.exec(line);
240	    if (m) out.push(m[1].trim());
241	  }
242	  return out;
243	}
244	
245	// Fold a second set of Context lines into the first, keeping order and dropping
246	// exact duplicates. Both sides are real scope — the item carries what its creator
247	// bound it to, the precondition adds what this occurrence found — and a set-write
248	// from either side would drop the other's.
249	export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];
250	
251	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
252	// already present and directly under the task path otherwise. Text surgery rather
253	// than a rebuild: the body also carries the creating precondition's Context and
254	// code-work's Delivered section, which belong to whoever wrote them.
255	export function withNotBefore(body, iso) {
256	  const text = String(body ?? '');
257	  if (NOT_BEFORE_RE.test(text)) {
258	    return iso
259	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
260	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
261	  }
262	  if (!iso) return text;
263	  const lines = text.split('\n');
264	  const at = lines.findIndex((l) => l.trim() !== '');
265	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
266	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
