285	// `heading`, but located by any of them, so a body written before a rename is updated
286	// in place instead of gaining a second section.
287	export function withSection(body, heading, lines, aliases = []) {
288	  if (!lines.length) return body;
289	  const text = String(body ?? '').replace(/\s*$/, '');
290	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
291	  const existing = text.split('\n');
292	  const wanted = new Set([heading, ...aliases].map((h) => `### ${h}`));
293	  const at = existing.findIndex((l) => wanted.has(l.trim()));
294	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
295	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
296	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
297	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
298	}
