30	export const ago = (at, now) => {
31	  const t = at == null ? null : (typeof at === 'number' ? at : new Date(at).getTime());
32	  return t ? `${duration(now - t)} ago` : '—';
33	};
34	export const until = (date, now) => (date ? `in ${duration(date.getTime() - now)}` : '—');
35	export const stamp = (iso) => (iso ? new Date(iso).toISOString().replace('T', ' ').slice(0, 16) : '—');
36	
37	// --- state and severity ---------------------------------------------------------
38	
39	export const STATE_UI = {
40	  [BLOCKED]:     { cls: 'blocked',   label: 'blocked' },
41	  [READY]:       { cls: 'ready',     label: 'ready' },
