    + '- Asked again at 2026-08-17T04:00:00Z.\n';
  const d = describeItem(item({ labels: [BLOCKED], body }), NOW);
  assert.equal(d.lastVerdict.reason, 'no signals in window');
  assert.equal(describeItem(item(), NOW).lastVerdict, null);
});

